with flattened_attrs as (select id, service, host, level, context, array_contains(map_keys(context), 'trace') as has_trace, coalesce(context['region'], 'none') as region_or_default from app_logs where service = 'checkout') select level, service, count_if(service = 'checkout') as checkout_events, sort_array(collect_set(level)) as level_list, count(distinct level) as distinct_levels, count(*) as num_rows, sort_array(collect_set(service)) as service_list, grouping_id() as grouping_level from flattened_attrs group by rollup (level, service) having distinct_levels < 1000 order by level nulls first;
